import{d as a,a as t,g as s,q as l,s as i,p as o,_ as d}from"./index-B-QX3yWK.js";const c={class:"about-us max-w-3xl mx-auto py-10 px-4"},n=a({__name:"AboutView",setup(r){return(v,e)=>(o(),t("div",c,e[0]||(e[0]=[s('<h1 class="text-3xl font-bold text-amber-700 mb-6" data-v-39629e5e>關於一佳香</h1><div class="mb-8 flex justify-center" data-v-39629e5e><img src="'+l+'" alt="品牌形象照" class="w-64 h-48 object-cover rounded-lg shadow" data-v-39629e5e></div><section class="mb-8" data-v-39629e5e><h2 class="text-xl font-semibold text-amber-600 mb-2" data-v-39629e5e>品牌故事</h2><p class="text-gray-700 leading-relaxed" data-v-39629e5e> 一佳香肉脯行創立於台東，數十年來堅持職人手作，嚴選台灣在地豬肉，傳承家族獨門配方，製作出黃金嬰兒豬肉鬆、蜜汁豬肉乾、五香豬肉條等經典美味。從在地小店到全台知名伴手禮品牌，始終堅持「用心做好每一片肉乾」的信念，讓每一口都吃得到家的溫度與思念。 </p></section><div class="mb-8 flex justify-center" data-v-39629e5e><img src="'+i+'" alt="門市照片" class="w-64 h-48 object-cover rounded-lg shadow" data-v-39629e5e></div><section class="mb-8" data-v-39629e5e><h2 class="text-xl font-semibold text-amber-600 mb-2" data-v-39629e5e>經營理念</h2><ul class="list-disc pl-6 text-gray-700" data-v-39629e5e><li data-v-39629e5e>嚴選台灣在地新鮮豬肉，堅持每日現做</li><li data-v-39629e5e>不添加防腐劑，保留食材原味</li><li data-v-39629e5e>傳承職人精神，手工翻炒、慢火烘烤</li><li data-v-39629e5e>用心服務每一位顧客，讓美味成為回憶</li></ul></section><section class="mb-8" data-v-39629e5e><h2 class="text-xl font-semibold text-amber-600 mb-2" data-v-39629e5e>品牌里程碑</h2><ul class="list-disc pl-6 text-gray-700" data-v-39629e5e><li data-v-39629e5e>1980 年：一佳香肉脯行創立於台東</li><li data-v-39629e5e>2005 年：推出黃金嬰兒豬肉鬆，成為台東伴手禮首選</li><li data-v-39629e5e>2018 年：榮獲台東十大伴手禮殊榮</li><li data-v-39629e5e>2023 年：官網上線，服務全台顧客</li></ul></section><section class="mb-8" data-v-39629e5e><h2 class="text-xl font-semibold text-amber-600 mb-2" data-v-39629e5e>社群連結</h2><a href="https://www.facebook.com/yiijiaxiang/?locale=zh_TW" target="_blank" class="text-blue-600 hover:underline" data-v-39629e5e>Facebook 粉絲專頁</a></section>',7)])))}}),b=d(n,[["__scopeId","data-v-39629e5e"]]);export{b as default};
